<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><h4>Expenses</h4><?php if(session()->getFlashdata('success')):?><div class="alert alert-success"><?=session()->getFlashdata('success')?></div><?php endif;?><?php if(session()->getFlashdata('error')):?><div class="alert alert-danger"><?=esc(session()->getFlashdata('error'))?></div><?php endif;?><form method="post" action="<?=site_url('expenses/save')?>" class="card card-body mb-3"><?=csrf_field()?><div class="row g-2"><div class="col-md-3"><select name="category_id" class="form-select" required><option value="">Category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=esc($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input name="amount" type="number" min=".01" step=".01" class="form-control" placeholder="Amount" required></div><div class="col-md-2"><select name="payment_mode" class="form-select"><option>cash</option><option>cheque</option><option>online</option></select></div><div class="col-md-2"><input name="reference_no" class="form-control" placeholder="Reference"></div><div class="col-md-3"><input name="description" class="form-control" placeholder="Description"></div></div><button class="btn btn-primary mt-2">Post Expense</button></form><table class="table table-sm"><thead><tr><th>No.</th><th>Category</th><th>Amount</th><th>Mode</th><th>Date</th></tr></thead><tbody><?php foreach($expenses as $e):?><tr><td><?=esc($e['expense_no'])?></td><td><?=esc($e['category_name'])?></td><td><?=number_format($e['amount'],2)?></td><td><?=esc($e['payment_mode'])?></td><td><?=esc($e['expense_at'])?></td></tr><?php endforeach;?></tbody></table><?= $this->endSection() ?>